item.aggregated_output:
  1	import {createHash} from "node:crypto";
  2	
  3	import {businessDayAccrual, diPercentAccrual} from "@offroad/financial-core";
  4	import Decimal from "decimal.js";
  5	import {z} from "zod";
  6	
  7	/**
  8	 * Executor of the method `build-interest-and-indexation-schedule` (v3, after the second independent
  9	 * review). Projects each series period by period with the factors its indenture writes: an annual
 10	 * rate accrues exponentially over business days of a 252-day year; a DI series compounds the DI
 11	 * factor with the spread factor; a "p% of DI" series compounds p times the daily DI; an IPCA series
 12	 * updates its nominal at each anniversary by the monthly index of the lagged month and accrues the
 13	 * spread on the updated nominal. A coupon is paid on its date: the accrual is split at the payment,
 14	 * what accrued before is paid, what accrues after is carried. The opening principal is a nominal
 15	 * (unit value times quantity, updated where the base holds the update); a ledger balance that
 16	 * includes accrued interest and costs is not a principal and names a gap. The accrued remuneration
 17	 * at the reference date comes from the base or the first coupon is declared incomplete. Rounding
 18	 * follows what each indenture writes. When the base does not say whether the IPCA update is
 19	 * capitalized or paid, both treatments are projected as scenarios. Nothing missing becomes zero: an
 20	 * absent amortization schedule leaves the principal projection insufficient in every aggregate, and
 21	 * the projected total is compared to the ledger's control so omitted series are named.
 22	 */
 23	const nonNegative = z.string().regex(/^\d+(\.\d+)?$/);
 24	const rate = z.string().regex(/^-?\d+(\.\d+)?$/);
 25	const nonEmpty = z.string().trim().min(1);
 26	const isoDate = z.string().regex(/^\d{4}-\d{2}-\d{2}$/);
 27	const isoMonth = z.string().regex(/^\d{4}-\d{2}$/);
 28	const unitSchema = z.enum(["BRL", "BRL thousand", "BRL million", "USD", "USD thousand"]);
 29	const anchorSchema = z.object({document: nonEmpty, page: z.number().int().positive().optional(), note: nonEmpty.optional(), clause: nonEmpty.optional()}).strict();
 30	type Anchor = z.infer<typeof anchorSchema>;
 31	const compare = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);
 32	
 33	export const projectionPeriodSchema = z.object({
 34	  id: nonEmpty,
 35	  start: isoDate,
 36	  end: isoDate,
 37	  /** Business days of the period, from the calendar the base cites (holidays included). */
 38	  businessDays: z.number().int().nonnegative(),
 39	  /** The calendar the count comes from. */
 40	  anchor: anchorSchema,
 41	}).strict();
 42	
 43	export const curveSchema = z.object({
 44	  id: nonEmpty,
 45	  kind: z.enum(["CDI", "IPCA"]),
 46	  /** Annual effective rate per period as a decimal, or the daily rate the source publishes (annualized by the executor as (1 + daily)^252 - 1). One of the two. */
 47	  annualRateByPeriod: z.record(nonEmpty, rate).nullable().default(null),
 48	  dailyRateByPeriod: z.record(nonEmpty, rate).nullable().default(null),
 49	  /** IPCA only: monthly variation by calendar month (YYYY-MM) as a decimal, for the anniversary updates. */
 50	  monthlyRateByMonth: z.record(isoMonth, rate).nullable().default(null),
 51	  source: z.object({title: nonEmpty, url: z.string().optional(), asOf: isoDate, anchor: anchorSchema}).strict(),
 52	}).strict();
 53	
 54	export const seriesRemunerationSchema = z.discriminatedUnion("type", [
 55	  z.object({type: z.literal("spread_over_index"), spreadPerYear: rate}).strict(),
 56	  z.object({type: z.literal("percent_of_index"), percentOfIndex: nonNegative}).strict(),
 57	  z.object({type: z.literal("fixed"), ratePerYear: rate}).strict(),
 58	]);
 59	
 60	/** Rounding the indenture writes for factors and amounts. */
 61	export const roundingSchema = z.object({
 62	  factorDecimals: z.number().int().min(4).max(16),
 63	  factorMode: z.enum(["round", "truncate"]),
 64	  amountDecimals: z.number().int().min(2).max(8),
 65	  amountMode: z.enum(["round", "truncate"]),
 66	  anchor: anchorSchema,
 67	}).strict();
 68	
 69	export const seriesInputSchema = z.object({
 70	  id: nonEmpty,
 71	  label: nonEmpty,
 72	  /** The nominal at the reference date and where it comes from; a ledger balance including accrued interest is not a nominal. */
 73	  openingPrincipal: z.object({value: nonNegative, basis: z.enum(["unit_value_x_quantity", "unit_value_x_quantity_updated", "trustee_report_nominal", "ledger_balance_including_accrued"]), anchor: anchorSchema}).strict(),
 74	  /** Remuneration accrued at the reference date since the last payment; null when the base does not hold it. */
 75	  openingAccrued: z.object({value: nonNegative, anchor: anchorSchema}).strict().nullable(),
 76	  indexer: z.enum(["CDI", "IPCA", "fixed", "unknown"]),
 77	  remuneration: seriesRemunerationSchema.nullable(),
 78	  /** Coupon payment dates with the business days from the start of the period that holds them, from the calendar the base cites. */
 79	  couponDates: z.array(z.object({date: isoDate, businessDaysFromPeriodStart: z.number().int().nonnegative()}).strict()).nullable(),
 80	  /** Scheduled principal payments; null when the base has no amortization schedule for the series. */
 81	  amortization: z.array(z.object({date: isoDate, amount: nonNegative}).strict()).nullable(),
 82	  /** IPCA only: how the update is treated (capitalized or paid); null when the indenture is not in the base, in which case both are projected. */
 83	  indexationTreatment: z.enum(["capitalized_principal", "cash_paid"]).nullable(),
 84	  /** IPCA only: the anniversary day and the lag in months the indenture writes for the index number. */
 85	  indexation: z.object({anniversaryDay: z.number().int().min(1).max(31), lagMonths: z.number().int().min(0).max(3), anchor: anchorSchema}).strict().nullable(),
 86	  rounding: roundingSchema.nullable(),
 87	  curveId: nonEmpty.nullable(),
 88	  anchors: z.object({balance: anchorSchema, terms: anchorSchema.nullable(), payments: anchorSchema.nullable(), amortization: anchorSchema.nullable()}).strict(),
 89	}).strict();
 90	
 91	export const interestScheduleInputSchema = z.object({
 92	  referenceDate: isoDate,
 93	  unit: unitSchema,
 94	  periods: z.array(projectionPeriodSchema).min(1),
 95	  curves: z.array(curveSchema).default([]),
 96	  series: z.array(seriesInputSchema).min(1),
 97	  /** The ledger's control: the series it holds and their nominal total, so omitted series are named and the projection's coverage is measured. */
 98	  ledgerControl: z.object({seriesIds: z.array(nonEmpty), grossDebt: nonNegative, anchor: anchorSchema}).strict().nullable().default(null),
 99	  /** The finance expense of the last closed period, to bridge against; null when not in the base. */
100	  accountingInterestLastPeriod: z.object({value: z.string().regex(/^-?\d+(\.\d+)?$/), periodId: nonEmpty, anchor: anchorSchema}).strict().nullable().default(null),
101	}).strict().superRefine((input, context) => {
102	  const periodIds = new Set<string>();
103	  const sorted = [...input.periods].sort((a, b) => compare(a.start, b.start));
104	  sorted.forEach((period, index) => {
105	    if (periodIds.has(period.id)) context.addIssue({code: "custom", path: ["periods"], message: `duplicate period ${period.id}`});
106	    periodIds.add(period.id);
107	    if (period.end <= period.start) context.addIssue({code: "custom", path: ["periods", index], message: `period ${period.id} ends before it starts`});
108	    if (index > 0 && sorted[index - 1]!.end !== period.start) context.addIssue({code: "custom", path: ["periods", index], message: `period ${period.id} does not start where ${sorted[index - 1]!.id} ends`});
109	  });
110	  if (sorted[0] && sorted[0].start !== input.referenceDate) context.addIssue({code: "custom", path: ["periods", 0], message: "the first period must start at the reference date"});
111	  const curveIds = new Set<string>();
112	  input.curves.forEach((curve, index) => {
113	    if (curveIds.has(curve.id)) context.addIssue({code: "custom", path: ["curves"], message: `duplicate curve ${curve.id}`});
114	    curveIds.add(curve.id);
115	    if ((curve.annualRateByPeriod === null) === (curve.dailyRateByPeriod === null)) context.addIssue({code: "custom", path: ["curves", index], message: `curve ${curve.id} must carry exactly one of annualRateByPeriod and dailyRateByPeriod`});
116	    if (curve.kind !== "IPCA" && curve.monthlyRateByMonth !== null) context.addIssue({code: "custom", path: ["curves", index], message: `curve ${curve.id} is not IPCA and carries monthly index variations`});
117	  });
118	  const seriesIds = new Set<string>();
119	  input.series.forEach((series, index) => {
120	    if (seriesIds.has(series.id)) context.addIssue({code: "custom", path: ["series"], message: `duplicate series ${series.id}`});
121	    seriesIds.add(series.id);
122	    const dates = new Set<string>();
123	    for (const coupon of series.couponDates ?? []) {
124	      if (dates.has(coupon.date)) context.addIssue({code: "custom", path: ["series", index, "couponDates"], message: `${series.id}: coupon date ${coupon.date} listed twice`});
125	      dates.add(coupon.date);
126	      const period = sorted.find((entry) => coupon.date > entry.start && coupon.date <= entry.end);
127	      if (period && coupon.businessDaysFromPeriodStart > period.businessDays) context.addIssue({code: "custom", path: ["series", index, "couponDates"], message: `${series.id}: coupon ${coupon.date} claims ${coupon.businessDaysFromPeriodStart} business days inside ${period.id}, which has ${period.businessDays}`});
128	    }
129	    if (series.indexer !== "IPCA" && (series.indexationTreatment !== null || series.indexation !== null)) context.addIssue({code: "custom", path: ["series", index], message: `${series.id}: indexation fields belong to IPCA series only`});
130	  });
131	});
132	export type InterestScheduleInput = z.input<typeof interestScheduleInputSchema>;
133	
134	type Calculation = {id: string; formula: string; operands: Record<string, string>; result: string; unit: string};
135	type Row = {
136	  period: string; opening_principal: string; indexation_factor: string; indexation_accrued: string; indexation_capitalized: string; indexation_paid: string;
137	  coupon_factor: string; coupon_accrued: string; coupon_paid: string; coupon_carried: string; principal_paid: string | null; closing_principal: string; calendar_anchor: Anchor;
138	};
139	type Totals = {cash_interest: string; cash_indexation: string; indexation_capitalized: string; principal_paid: string | null};
140	type SeriesSchedule = {
141	  series_id: string; label: string; indexer: string; remuneration: string;
142	  opening_principal: {value: string; basis: string; anchor: Anchor};
143	  opening_accrued: {value: string; anchor: Anchor} | null;
144	  first_coupon_complete: boolean;
145	  curve: {id: string; asOf: string; title: string; anchor: Anchor} | null;
146	  rounding: {factorDecimals: number; factorMode: string; amountDecimals: number; amountMode: string; anchor: Anchor} | null;
147	  principal_projection: "scheduled" | "insufficient_evidence";
148	  treatment: "capitalized_principal" | "cash_paid" | "not_indexed";
149	  /** Present only when the base does not say how the IPCA update is treated: both projections, side by side. */
150	  treatment_scenarios: Array<{treatment: "capitalized_principal" | "cash_paid"; rows: Row[]; totals: Totals}> | null;
151	  rows: Row[];
152	  totals: Totals;
153	  anchors: {balance: Anchor; terms: Anchor | null; payments: Anchor | null; amortization: Anchor | null; indexation: Anchor | null};
154	};
155	
156	export type InterestScheduleOutput = {
157	  schema_version: "method.build-interest-and-indexation-schedule.v3";
158	  reference_date: string;
159	  unit: string;
160	  state: "complete" | "partial" | "blocked";
161	  block_reasons: string[];
162	  assumptions: string[];
163	  schedule_by_series: SeriesSchedule[];
164	  schedule_aggregate: {
165	    by_period: Array<{period: string; cash_interest: string; cash_indexation: string; indexation_capitalized: string; principal_paid: string | null; closing_principal: string | null}>;
166	    by_indexer: Array<{indexer: string; cash_interest: string; cash_indexation: string; indexation_capitalized: string; closing_principal: string | null; series: string[]}>;
167	    opening_principal_projected: string;
168	    principal_projection_complete: boolean;
169	    treatment_scenarios_pending: string[];
170	  } | null;
171	  ledger_coverage: {projected: string; ledger: string; share: string; series_omitted: string[]; anchor: Anchor} | null;
172	  accounting_bridge: {projected: string | null; accounting: string; difference: string | null; period: string; anchor: Anchor; state: "compared" | "insufficient_evidence"; reason: string | null} | null;
173	  uncovered_series: Array<{series_id: string; reason: string; state: "insufficient_evidence"}>;
174	  trace: {calculations: Calculation[]; inputFingerprint: string; outputFingerprint: string};
175	};
176	
177	const d = (value: Decimal.Value) => new Decimal(value);
178	const out = (value: Decimal) => value.toDecimalPlaces(8).toFixed();
179	const stableStringify = (value: unknown): string => JSON.stringify(value, (_key, inner: unknown) => (inner && typeof inner === "object" && !Array.isArray(inner) ? Object.fromEntries(Object.entries(inner as Record<string, unknown>).sort(([a], [b]) => compare(a, b))) : inner));
180	const fingerprint = (value: unknown) => createHash("sha256").update(stableStringify(value)).digest("hex");
181	const sortRecord = <T,>(record: Record<string, T> | null) => (record ? Object.fromEntries(Object.entries(record).sort(([a], [b]) => compare(a, b))) : null);
182	
183	function canonical(input: z.infer<typeof interestScheduleInputSchema>) {
184	  return {
185	    ...input,
186	    periods: [...input.periods].sort((a, b) => compare(a.start, b.start)),
187	    curves: [...input.curves].sort((a, b) => compare(a.id, b.id)).map((curve) => ({...curve, annualRateByPeriod: sortRecord(curve.annualRateByPeriod), dailyRateByPeriod: sortRecord(curve.dailyRateByPeriod), monthlyRateByMonth: sortRecord(curve.monthlyRateByMonth)})),
188	    series: [...input.series].sort((a, b) => compare(a.id, b.id)).map((series) => ({...series, couponDates: series.couponDates ? [...series.couponDates].sort((a, b) => compare(a.date, b.date)) : null, amortization: series.amortization ? [...series.amortization].sort((a, b) => compare(a.date, b.date) || compare(a.amount, b.amount)) : null})),
189	    ledgerControl: input.ledgerControl ? {...input.ledgerControl, seriesIds: [...input.ledgerControl.seriesIds].sort(compare)} : null,
190	  };
191	}
192	
193	const describeRemuneration = (series: z.infer<typeof seriesInputSchema>) => {
194	  const remuneration = series.remuneration!;
195	  if (remuneration.type === "fixed") return `fixed ${remuneration.ratePerYear} per year`;
196	  if (remuneration.type === "percent_of_index") return `${remuneration.percentOfIndex} of ${series.indexer}`;
197	  return `${series.indexer} + ${remuneration.spreadPerYear} per year`;
198	};
199	const addMonths = (isoMonth: string, months: number) => { const [year, month] = isoMonth.split("-").map(Number) as [number, number]; const index = year * 12 + (month - 1) + months; return `${Math.floor(index / 12)}-${String((index % 12) + 1).padStart(2, "0")}`; };
200	/** Anniversary dates strictly after `start` and up to `end`, on the series' anniversary day (month-end clipped). */
201	function anniversaries(start: string, end: string, day: number): string[] {
202	  const dates: string[] = [];
203	  let month = start.slice(0, 7);
204	  for (let guard = 0; guard < 120; guard += 1) {
205	    const [year, monthNumber] = month.split("-").map(Number) as [number, number];
206	    const lastDay = new Date(Date.UTC(year, monthNumber, 0)).getUTCDate();
207	    const date = `${month}-${String(Math.min(day, lastDay)).padStart(2, "0")}`;
208	    if (date > end) break;
209	    if (date > start) dates.push(date);
210	    month = addMonths(month, 1);
211	  }
212	  return dates;
213	}
214	
215	export function buildInterestAndIndexationSchedule(raw: InterestScheduleInput): InterestScheduleOutput {
216	  const input = canonical(interestScheduleInputSchema.parse(raw));
217	  const calculations: Calculation[] = [];
218	  const record = (calculation: Omit<Calculation, "unit">, unit: string = input.unit) => calculations.push({...calculation, unit});
219	  const curves = new Map(input.curves.map((curve) => [curve.id, curve]));
220	  const uncovered: InterestScheduleOutput["uncovered_series"] = [];
221	  const assumptions = new Set<string>();
222	  const blockReasons: string[] = [];
223	  const schedules: SeriesSchedule[] = [];
224	
225	  /** Annual rate of a curve for a period: as published, or annualized from the daily rate the source publishes. */
226	  const annualRate = (curve: z.infer<typeof curveSchema>, periodId: string): string | null => {
227	    if (curve.annualRateByPeriod) return curve.annualRateByPeriod[periodId] ?? null;
228	    const daily = curve.dailyRateByPeriod?.[periodId];
229	    if (daily === undefined) return null;
230	    const annual = d(daily).plus(1).pow(252).minus(1);
231	    record({id: `financial.daily_rate_annualized:${curve.id}:${periodId}`, formula: "(1 + dailyRate)^252 - 1", operands: {dailyRate: daily}, result: out(annual)}, "x");
232	    return out(annual);
233	  };
234	
235	  for (const series of input.series) {
236	    if (series.openingPrincipal.basis === "ledger_balance_including_accrued") { uncovered.push({series_id: series.id, reason: `the opening figure of ${series.label} is a ledger balance that includes accrued interest, monetary variation and transaction costs; the nominal (unit value times quantity, updated where indexed) is not in the base`, state: "insufficient_evidence"}); continue; }
237	    if (series.indexer === "unknown" || series.remuneration === null) { uncovered.push({series_id: series.id, reason: `no source in the base states the indexer or the remuneration of ${series.label}`, state: "insufficient_evidence"}); continue; }
238	    if (!series.anchors.terms) { uncovered.push({series_id: series.id, reason: `the terms of ${series.label} carry no anchor; a term without a source is not a term`, state: "insufficient_evidence"}); continue; }
239	    if (series.couponDates === null || !series.anchors.payments) { uncovered.push({series_id: series.id, reason: `the payment dates of ${series.label} are not in the base; coupons cannot be placed in time`, state: "insufficient_evidence"}); continue; }
240	    if ((series.indexer === "CDI" && series.remuneration.type === "fixed") || (series.indexer === "fixed" && series.remuneration.type !== "fixed") || (series.indexer === "IPCA" && series.remuneration.type !== "spread_over_index")) {
241	      uncovered.push({series_id: series.id, reason: `the remuneration type of ${series.label} (${series.remuneration.type}) does not match its indexer (${series.indexer})`, state: "insufficient_evidence"}); continue;
242	    }
243	    const curve = series.curveId ? curves.get(series.curveId) ?? null : null;
244	    if (series.indexer !== "fixed") {
245	      if (!curve) { uncovered.push({series_id: series.id, reason: `no registered curve for the ${series.indexer} of ${series.label}; a curve without source and date does not enter`, state: "insufficient_evidence"}); continue; }
246	      if (curve.kind !== series.indexer) { uncovered.push({series_id: series.id, reason: `curve ${curve.id} is a ${curve.kind} curve and ${series.label} is indexed to ${series.indexer}`, state: "insufficient_evidence"}); continue; }
247	      if (series.indexer === "CDI" && input.periods.some((period) => annualRate(curve, period.id) === null)) { uncovered.push({series_id: series.id, reason: `curve ${curve.id} does not cover every projected period`, state: "insufficient_evidence"}); continue; }
248	      if (curve.source.asOf !== input.referenceDate) assumptions.add(`curve ${curve.id} is dated ${curve.source.asOf}, not the reference date ${input.referenceDate}: the projection uses it as the base scenario and does not call it the curve of the reference date`);
249	    }
250	    if (series.indexer === "IPCA") {
251	      if (!series.indexation) { uncovered.push({series_id: series.id, reason: `the anniversary day and the index lag of ${series.label} are not in the base; the monthly update cannot be placed`, state: "insufficient_evidence"}); continue; }
252	      if (!curve!.monthlyRateByMonth) { uncovered.push({series_id: series.id, reason: `curve ${curve!.id} carries no monthly index variations; the IPCA update of ${series.label} needs them`, state: "insufficient_evidence"}); continue; }
253	      const needed = input.periods.flatMap((period) => anniversaries(period.start, period.end, series.indexation!.anniversaryDay)).map((date) => addMonths(date.slice(0, 7), -series.indexation!.lagMonths));
254	      const missing = needed.filter((month) => curve!.monthlyRateByMonth![month] === undefined);
255	      if (missing.length > 0) { uncovered.push({series_id: series.id, reason: `curve ${curve!.id} lacks the monthly variation of ${[...new Set(missing)].join(", ")} that the anniversaries of ${series.label} need`, state: "insufficient_evidence"}); continue; }
256	      assumptions.add(`IPCA updates are applied at each anniversary with the monthly variation of the lagged month; the pro rata between anniversaries by business days of the month is not projected (declared approximation)`);
257	      if (series.indexationTreatment === null) assumptions.add(`${series.id}: the base does not say whether the IPCA update is capitalized or paid; both treatments are projected as scenarios and neither is chosen`);
258	    }
259	    if (!series.openingAccrued) assumptions.add(`${series.id}: the remuneration accrued at ${input.referenceDate} is not in the base; the first coupon is declared incomplete and carries only what accrues from the reference date`);
260	    const principalProjection: "scheduled" | "insufficient_evidence" = series.amortization && series.anchors.amortization ? "scheduled" : "insufficient_evidence";
261	    const rounding = series.rounding;
262	    const roundFactor = (value: Decimal) => (rounding ? value.toDecimalPlaces(rounding.factorDecimals, rounding.factorMode === "truncate" ? Decimal.ROUND_DOWN : Decimal.ROUND_HALF_UP) : value.toDecimalPlaces(8));
263	    const roundAmount = (value: Decimal) => (rounding ? value.toDecimalPlaces(rounding.amountDecimals, rounding.amountMode === "truncate" ? Decimal.ROUND_DOWN : Decimal.ROUND_HALF_UP) : value.toDecimalPlaces(8));
264	    if (!rounding) assumptions.add(`${series.id}: the indenture's rounding of factors and amounts is not in the base; eight decimals, rounded, are used (declared)`);
265	
266	    const couponFactorFor = (businessDays: number, periodId: string, label: string): Decimal => {
267	      const remuneration = series.remuneration!;
268	      if (businessDays === 0) return d(0);
269	      if (remuneration.type === "fixed") {
270	        const accrual = businessDayAccrual(remuneration.ratePerYear, businessDays);
271	        record({id: `financial.business_day_accrual:${series.id}:${periodId}:${label}`, formula: "(1 + ratePerYear)^(businessDays/252) - 1", operands: {ratePerYear: remuneration.ratePerYear, businessDays: String(businessDays)}, result: accrual.value}, "x");
272	        return roundFactor(d(accrual.value));
273	      }
274	      if (remuneration.type === "percent_of_index") {
275	        const di = annualRate(curve!, periodId)!;
276	        const accrual = diPercentAccrual(di, remuneration.percentOfIndex, businessDays);
277	        record({id: `financial.di_percent_accrual:${series.id}:${periodId}:${label}`, formula: "(1 + ((1 + DI)^(1/252) - 1) * p)^businessDays - 1", operands: {annualDi: di, percentOfIndex: remuneration.percentOfIndex, businessDays: String(businessDays)}, result: accrual.value}, "x");
278	        return roundFactor(d(accrual.value));
279	      }
280	      if (series.indexer === "CDI") {
281	        const di = annualRate(curve!, periodId)!;
282	        const fatorDi = businessDayAccrual(di, businessDays);
283	        const fatorSpread = businessDayAccrual(remuneration.spreadPerYear, businessDays);
284	        const factor = roundFactor(d(fatorDi.value)).plus(1).times(roundFactor(d(fatorSpread.value)).plus(1)).minus(1);
285	        record({id: `financial.di_spread_factor:${series.id}:${periodId}:${label}`, formula: "(1 + fatorDI) * (1 + fatorSpread) - 1", operands: {fatorDI: fatorDi.value, fatorSpread: fatorSpread.value, annualDi: di, spreadPerYear: remuneration.spreadPerYear, businessDays: String(businessDays)}, result: out(factor)}, "x");
286	        return roundFactor(factor);
287	      }
288	      const spread = businessDayAccrual(remuneration.spreadPerYear, businessDays);
289	      record({id: `financial.business_day_accrual:${series.id}:${periodId}:${label}`, formula: "(1 + spreadPerYear)^(businessDays/252) - 1", operands: {spreadPerYear: remuneration.spreadPerYear, businessDays: String(businessDays)}, result: spread.value}, "x");
290	      return roundFactor(d(spread.value));
291	    };
292	
293	    /** The IPCA update factor of a period, computed and recorded once whatever the number of treatment scenarios. */
294	    const indexationFactors = new Map<string, Decimal>();
295	    const indexationFactorFor = (period: z.infer<typeof projectionPeriodSchema>): Decimal => {
296	      if (series.indexer !== "IPCA") return d(0);
297	      const cached = indexationFactors.get(period.id);
298	      if (cached) return cached;
299	      let factor = d(1);
